g.PackageFamilyName)" -Name "Value" -Value "Allow";"SPEECH DRIVER mic consent set for $($pkg.PackageFamilyName)";Add-Type -AssemblyName UIAutomationClient,UIAutomationTypes;Add-Type -AssemblyName System.Speech;Add-Type "using System;using System.Runtime.InteropServices;public static class SPI {[DllImport(""user32.dll"")] public static extern bool SetForegroundWindow(IntPtr h);}";$log=Join-Path $env:LOCALAPPDATA "Packages\$($pkg.PackageFamilyName)\LocalState\console.log";Remove-Item $log -ErrorAction SilentlyContinue;Start-Process explorer.exe -ArgumentList "shell:AppsFolder\$($pkg.PackageFamilyName)!App";$deadline=(Get-Date).AddSeconds(30);$window=$null;do{Start-Sleep -Milliseconds 300;$ws=[System.Windows.Automation.AutomationElement]::RootElement.FindAll([System.Windows.Automation.TreeScope]::Children,[System.Windows.Automation.Condition]::TrueCondition);$window=$ws|Where-Object {$_.Current.Name -eq "XplatSpeech"}|Select-Object -First 1}while(-not $window -and (Get-Date) -lt $deadline);if(-not $window){if(Test-Path $log){Get-Content $log};throw "No speech window"};[SPI]::SetForegroundWindow([IntPtr]$window.Current.NativeWindowHandle)|Out-Null;$synth=New-Object System.Speech.Synthesis.SpeechSynthesizer;$synth.SetOutputToDefaultAudioDevice();$phrase="the quick brown fox jumps over the lazy dog";$speaks=0;$clickedConsent=$false;$deadline=(Get-Date).AddSeconds(200);$sawDone=$false;while((Get-Date) -lt $deadline){$content="";if(Test-Path $log){$content=Get-Content $log -Raw};if($content -match "SPEECH DONE"){$sawDone=$true;break};try{$tops=[System.Windows.Automation.AutomationElement]::RootElement.FindAll([System.Windows.Automation.TreeScope]::Children,[System.Windows.Automation.Condition]::TrueCondition);$sig=($tops|ForEach-Object {$_.Current.Name}) -join "|";if($sig -ne $lastTopSig){$lastTopSig=$sig;"SPEECH DRIVER TOPS: "+$sig}}catch{"SPEECH DRIVER tops scan error "+$_};if(-not $clickedConsent){try{foreach($top in $tops){$texts=$top.FindAll([System.Windows.Automation.